// import and run Promise polyfill first (😠 #hateIE)
import { polyfill as PromisePolyfill} from "es6-promise";
PromisePolyfill();

// Imports and registers
import {HMIWebExperionServicesSuppressionStatus} from '@hw/experionservices/unbundled/HMIWebExperionServicesSuppressionStatus';
import {SuppressionStatusElement} from '@hw/hmiweb-suppression-status';
import {HmiwebTsLogger} from "@hw/hmiweb-core/js/logging/HmiwebTsLogger";
import {HmiwebTsLocalisation} from "@hw/hmiweb-core/js/localisation/HmiwebTsLocalisation";

let service = new HMIWebExperionServicesSuppressionStatus();
service.register(HmiwebTsLogger.simpleInstance);
SuppressionStatusElement.register(HmiwebTsLogger.instance, HmiwebTsLocalisation.instance, service.suppressionStatusService);

window.addEventListener("unload", () => {
    service.dispose();
    service = null;
});

// styles
import './styles/main.scss';

// git stamp
declare var REPONAME: string;
declare var VERSION: string;
declare var BRANCH: string;
declare var COMMITHASH: string;
const commitInfo = {
    repoName: REPONAME,
    version: VERSION,
    branch: BRANCH,
    commit: COMMITHASH
};

